import numpy as np
def traj(Vamp,C_uF,tmax=30,targets=[0.1,0.1815,0.262,0.3,0.35,0.4]):
    C=C_uF*1e-6; vs=0.0; t=0; dt=2e-5; out={}
    th=np.linspace(0,np.pi,300)
    while t<tmax:
        I=np.maximum((Vamp*np.sin(th)-vs-0.3)/5000,0)
        Iavg=np.trapezoid(I,th)/np.pi - vs/10e6
        vs=max(vs+Iavg/C*dt,0)
        t+=dt
        for tg in targets:
            if tg not in out and vs>=tg: out[tg]=t
    return out,vs
print('initial main V=0.712 C150 gate2.9:',traj(0.712,150))
