import numpy as np
def times(Vamp,C_uF=220,tmax=60):
    C=C_uF*1e-6; vs=0.0; t=0; dt=1e-5; out={}; th=np.linspace(0,np.pi,600); s=np.sin(th)
    while t<tmax:
